const ALL_PERM_KEYS = PERMISSION_CATEGORIES.flatMap(c => c.permissions.map(p => p.key));

function buildPerms(overrides = {}) {
  const p = {};
  ALL_PERM_KEYS.forEach(k => { p[k] = overrides[k] !== undefined ? overrides[k] : false; });
  return p;
}

